      "poi_id": "p10",
      "kind": "activity",
      "must_do_id": null,
      "note": "Roma Norte strolls with leafy streets and little balconies, the kind of local life you feel just by walking."
    },
    {
      "poi_id": "p14",
      "kind": "meal",
      "must_do_id": null,
      "note": "Tiny tacos, big flavour, and the kind of counter where you order one more without thinking."
    },
    {
      "poi_id": "p11",
      "kind": "activity",
      "must_do_id": null,
      "note": "Masks, capes, and a crowd that roars: the arena turns a Sunday night into pure theatre."
    }
